  sessions discussion_board_user_sessions[]
  passwordResets discussion_board_user_password_resets[]
  userAdminRequests discussion_board_user_admin_requests[] @relation("discussion_board_user_admin_requests_of_discussion_boa_a5d084bb")
  reviewedUserAdminRequests discussion_board_user_admin_requests[] @relation("discussion_board_user_admin_requests_of_reviewer_id")
  auditLogs discussion_board_user_audit_logs[] @relation("discussion_board_user_audit_logs_of_discussion_board_user_id")
  performedAuditLogs discussion_board_user_audit_logs[] @relation("discussion_board_user_audit_logs_of_actor_user_id")
  createdSections discussion_board_sections[] @relation("discussion_board_sections_of_creator_id")
  modifiedSections discussion_board_sections[] @relation("discussion_board_sections_of_modifier_id")
  articles discussion_board_articles[]
