  adminActionLogs discussion_board_admin_action_logs[] @relation("discussion_board_admin_action_logs_of_administrator_id")
  originalAuthorActionLogs discussion_board_admin_action_logs[] @relation("discussion_board_admin_action_logs_of_original_author_id")
  bans discussion_board_bans[] @relation("discussion_board_bans_of_discussion_board_user_id")
