    {
      body: {
        userId: userAuth.id,
        reason: RandomGenerator.paragraph({ sentences: 3 }),
      } satisfies IDiscussionBoardBan.ICreate,
    },
  );
  // If ban succeeds, validate the banned user cannot refresh
  if (banResult) {
    typia.assert(banResult);
