        host: connection.host,
      };
      await api.functional.discussionBoard.auth.user.refresh(
        bannedRefreshConnection,
        {
          body: {
            refresh_token: refreshToken,
          } satisfies IDiscussionBoardUser.IRefresh,
        },
      );
    });
  }
}

