  const anotherArticle =
    await generate_random_discussion_board_user_articles_create(
      userAConnection,
      {},
    );
  typia.assert(anotherArticle);
  TestValidator.equals(
    "User A can still create articles",
    anotherArticle.author.id,
    userA.id,
  );
}

