  // 2. Request action log list with default pagination (no filters)
  const result =
    await api.functional.discussionBoard.user.adminActionLogs.index(
      adminConnection,
      {
        body: {} satisfies IDiscussionBoardAdminActionLog.IRequest,
      },
    );
