/**
 * Test filtering ban history by action type to retrieve only BAN actions.
 * 1. Filter by action_type: 'BAN' and validate all records are BAN actions
 * 2. Filter by action_type: 'UNBAN' and validate all records are UNBAN actions
 * This validates the action type filter functionality for compliance audits.
 */
export async function test_api_ban_history_filter_by_action_type(
  connection: api.IConnection,
): Promise<void> {
  // Test 1: Filter by BAN action type
  const banHistoryBanOnly =
    await api.functional.discussionBoard.ban_histories.index(connection, {
      body: {
        action_type: "BAN",
      } satisfies IDiscussionBoardBanHistory.IRequest,
    });
  typia.assert(banHistoryBanOnly);
  // Validate all returned records have actionType === 'BAN'
  TestValidator.predicate(
    "all records should have actionType 'BAN'",
    banHistoryBanOnly.data.every((record) => record.actionType === "BAN"),
  );
  // Validate no UNBAN records are included
  TestValidator.predicate(
    "no UNBAN records should be present",
    !banHistoryBanOnly.data.some((record) => record.actionType === "UNBAN"),
  );
  // Test 2: Filter by UNBAN action type
  const banHistoryUnbanOnly =
    await api.functional.discussionBoard.ban_histories.index(connection, {
      body: {
        action_type: "UNBAN",
      } satisfies IDiscussionBoardBanHistory.IRequest,
    });
  typia.assert(banHistoryUnbanOnly);
  // Validate all returned records have actionType === 'UNBAN'
  TestValidator.predicate(
    "all records should have actionType 'UNBAN'",
    banHistoryUnbanOnly.data.every((record) => record.actionType === "UNBAN"),
  );
  // Validate no BAN records are included
  TestValidator.predicate(
    "no BAN records should be present",
    !banHistoryUnbanOnly.data.some((record) => record.actionType === "BAN"),
  );
}

