export async function getDiscussionBoardUserSessionsSessionId(props: {
  user: UserPayload;
  sessionId: string;
}): Promise<IDiscussionBoardUserSession> {
  const session =
    await MyGlobal.prisma.discussion_board_user_sessions.findUnique({
      where: { id: props.sessionId },
