        id: v4(),
        value: normalizedValue,
        created_at: new Date(),
        updated_at: new Date(),
      },
      select: { id: true, value: true },
    });
  }
  // 6. Check existing association
  const existingAssociation =
    await MyGlobal.prisma.discussion_board_article_tags.findUnique({
