   */
  @TypedRoute.Patch()
  public async index(
    @TypedBody()
    body: IDiscussionBoardBan.IRequest,
  ): Promise<IPageIDiscussionBoardBan.ISummary> {
    try {
      return await patchDiscussionBoardBans({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
